	public class ServiceHostEngine : IDisposable
	{
		private IEventPublisher _eventPublisher;

		private IList<ServiceHost> _services;

		public bool Iniciado
		{
			get
			{
				if (_services != null && _services.Any())
				{
					return _services.All((ServiceHost x) => x.State == CommunicationState.Opened);
				}
				return false;
			}
		}

		public ServiceHostEngine(IEnumerable<ServiceHost> services, IEventPublisher eventPublisher)
		{
			_services = services.ToList();
			_eventPublisher = eventPublisher;
		}

		public void Start()
		{
			OnAntesIniciarServicos();
			foreach (ServiceHost service in _services)
			{
				service.Open();
			}
			OnDepoisIniciarServicos();
		}

		public void Stop()
		{
			OnAntesPararServicos();
			foreach (ServiceHost service in _services)
			{
				service.Close();
			}
			OnDepoisPararServicos();
		}

		protected virtual void OnAntesIniciarServicos()
		{
			_eventPublisher.Publish(new AntesIniciarServicoEvent());
		}

		protected virtual void OnDepoisIniciarServicos()
		{
			_eventPublisher.Publish(new DepoisIniciarServicoEvent());
		}

		protected virtual void OnAntesPararServicos()
		{
			_eventPublisher.Publish(new AntesPararServicoEvent());
		}

		protected virtual void OnDepoisPararServicos()
		{
			_eventPublisher.Publish(new DepoisPararServicoEvent());
		}

		public void Dispose()
		{
			Stop();
			_services.Clear();
			_services = null;
			_eventPublisher = null;
		}
	}
	public class WcfServiceBasicHttpFactory : WcfServiceHttpFactory
	{
		public override IEnumerable<ServiceHost> Servicos => base.Tipos.Where((Type t) => t.GetCustomAttributes(typeof(ProtectedAttribute), inherit: true).Length == 0 && t.GetCustomAttributes(typeof(WebHttpAttribute), inherit: true).Length == 0 && t.GetCustomAttributes(typeof(NoProtectedAttribute), inherit: true).Length == 0).Select(base.CreateServiceHostEx);

		public WcfServiceBasicHttpFactory(EndPointWcf endPoint)
			: base(endPoint)
		{
		}

		protected override ServiceHost CreateServiceHost(Type serviceType, Uri[] baseAddresses)
		{
			ServiceHost serviceHost = base.CreateServiceHost(serviceType, baseAddresses);
			ApplyEndPoint(serviceHost, new BasicHttpBinding
			{
				OpenTimeout = TimeSpan.FromHours(12.0),
				ReceiveTimeout = TimeSpan.FromHours(12.0),
				CloseTimeout = TimeSpan.FromHours(12.0),
				SendTimeout = TimeSpan.FromHours(12.0),
				MaxReceivedMessageSize = 2147483647L
			});
			return serviceHost;
		}
	}
	public abstract class WcfServiceHttpFactory : SimpleInjectorServiceHostFactory
	{
		protected readonly EndPointWcf _endPoint;

		protected Type Interface;

		protected Uri[] Uri;

		protected Container Container = Bootstrapper.Container;

		protected IEnumerable<Type> Tipos => from type in Assembly.GetExecutingAssembly().GetTypes()
			where type.GetCustomAttributes(typeof(ServiceBehaviorAttribute), inherit: true).Length != 0
			select type;

		public abstract IEnumerable<ServiceHost> Servicos { get; }

		protected WcfServiceHttpFactory(EndPointWcf endPoint)
		{
			_endPoint = endPoint;
		}

		protected override ServiceHost CreateServiceHost(Type serviceType, Uri[] baseAddresses)
		{
			ProcessarUri(serviceType);
			return new SimpleInjectorServiceHost(Container, serviceType, Uri);
		}

		protected virtual void ProcessarUri(Type serviceType)
		{
			Interface = serviceType.GetInterfaces().FirstOrDefault();
			Uri = new Uri[1]
			{
				new Uri($"http://{_endPoint}/{Interface?.Name}")
			};
		}

		protected virtual void ApplyEndPoint(ServiceHost host, Binding binding)
		{
			host.AddServiceEndpoint(Interface, binding, Uri[0]);
		}

		public ServiceHost CreateServiceHostEx(Type serviceType)
		{
			return CreateServiceHost(serviceType, Uri);
		}
	}
	public class WcfServiceServerCustomHttpFactory : WcfServiceHttpFactory
	{
		public override IEnumerable<ServiceHost> Servicos => base.Tipos.Where((Type t) => t.GetCustomAttributes(typeof(ProtectedAttribute), inherit: true).Length != 0 || t.GetCustomAttributes(typeof(NoProtectedAttribute), inherit: true).Length != 0).Select(base.CreateServiceHostEx);

		public WcfServiceServerCustomHttpFactory(EndPointWcf endPoint)
			: base(endPoint)
		{
		}

		protected override ServiceHost CreateServiceHost(Type serviceType, Uri[] baseAddresses)
		{
			ServiceHost serviceHost = base.CreateServiceHost(serviceType, baseAddresses);
			ServerCustomBinding binding = new ServerCustomBinding(GetContentEncryption(serviceType))
			{
				TextEncoding = Encoding.UTF8,
				MaxReceivedMessageSize = 2147483647L,
				MaxBufferSize = int.MaxValue,
				CloseTimeout = TimeSpan.FromHours(12.0),
				OpenTimeout = TimeSpan.FromHours(12.0),
				ReceiveTimeout = TimeSpan.FromHours(12.0)
			};
			ApplyEndPoint(serviceHost, binding);
			ApplyAuthenticationManager(serviceHost);
			ApplyAuthorizationPolicy(serviceHost);
			return serviceHost;
		}

		protected void ApplyAuthenticationManager(ServiceHostBase host)
		{
			host.Authentication.ServiceAuthenticationManager = new ServerAuthenticationManager(Container.GetInstance<IUsuarioAppService>(), Container.GetInstance<ITokenAppService>(), Container.GetInstance<IHabilitacaoAppService>());
		}

		protected void ApplyAuthorizationPolicy(ServiceHostBase host)
		{
			List<IAuthorizationPolicy> list = new List<IAuthorizationPolicy>
			{
				new ServerAuthorizationPolicy()
			};
			host.Authorization.ExternalAuthorizationPolicies = list.AsReadOnly();
			host.Authorization.PrincipalPermissionMode = PrincipalPermissionMode.Custom;
		}

		private ContentEncryptionType GetContentEncryption(Type serviceType)
		{
			if (serviceType.GetCustomAttributes(typeof(ProtectedAttribute), inherit: true).Length == 0)
			{
				return ContentEncryptionType.None;
			}
			return ContentEncryptionType.All;
		}
	}
	public class WcfServiceWebHttpFactory : WcfServiceHttpFactory
	{
		public override IEnumerable<ServiceHost> Servicos => base.Tipos.Where((Type t) => t.GetCustomAttributes(typeof(WebHttpAttribute), inherit: true).Length != 0).Select(base.CreateServiceHostEx);

		public WcfServiceWebHttpFactory(EndPointWcf endPoint)
			: base(endPoint)
		{
		}

		protected override ServiceHost CreateServiceHost(Type serviceType, Uri[] baseAddresses)
		{
			ServiceHost serviceHost = base.CreateServiceHost(serviceType, baseAddresses);
			WebHttpBinding webHttpBinding = new WebHttpBinding
			{
				MaxReceivedMessageSize = 2147483647L,
				MaxBufferSize = int.MaxValue,
				ReaderQuotas = 
				{
					MaxStringContentLength = int.MaxValue,
					MaxArrayLength = int.MaxValue,
					MaxBytesPerRead = int.MaxValue
				}
			};
			if (Streamed(serviceType))
			{
				webHttpBinding.TransferMode = TransferMode.StreamedResponse;
				webHttpBinding.SendTimeout = TimeSpan.FromMinutes(30.0);
			}
			ApplyEndPoint(serviceHost, webHttpBinding);
			if (!DeveAplicarAutenticacao(serviceType))
			{
				return serviceHost;
			}
			ApplyAuthenticationManager(serviceHost, serviceType.Name.Contains("Controller"));
			ApplyAuthorizationPolicy(serviceHost);
			return serviceHost;
		}

		private static bool Streamed(Type serviceType)
		{
			return ((WebHttpAttribute[])serviceType.GetCustomAttributes(typeof(WebHttpAttribute), inherit: true)).Any((WebHttpAttribute a) => a.Streamed);
		}

		private bool DeveAplicarAutenticacao(Type serviceType)
		{
			if (!serviceType.Name.Contains("UsuariosApiService") && !serviceType.Name.Contains("ColetorDadosModuleService") && !serviceType.Name.Contains("RestauranteMobileModuleService") && !serviceType.Name.Contains("ForcaVendasModuleService") && !serviceType.Name.Contains("ConversorModuleService") && !serviceType.Name.Contains("UsuarioController") && !serviceType.Name.Contains("PerfilController") && !serviceType.Name.Contains("EmpresaController") && !serviceType.Name.Contains("AuthController") && !serviceType.Name.Contains("ConfiguracaoController") && !serviceType.Name.Contains("VersaoServidorController"))
			{
				return !serviceType.Name.Contains("AtualizacaoEstacaoController");
			}
			return false;
		}

		protected override void ProcessarUri(Type serviceType)
		{
			Interface = serviceType.GetInterfaces().FirstOrDefault();
			WebHttpAttribute[] array = (WebHttpAttribute[])serviceType.GetCustomAttributes(typeof(WebHttpAttribute), inherit: true);
			if (!string.IsNullOrEmpty(array[0].Endpoint))
			{
				Uri = new Uri[1]
				{
					new Uri($"http://{_endPoint}/api/{array[0].Endpoint}")
				};
				return;
			}
			string name = Interface.Name;
			Uri = ((!name.Contains("ApiService")) ? new Uri[1]
			{
				new Uri($"http://{_endPoint}/{Interface?.Name}")
			} : new Uri[1]
			{
				new Uri($"http://{_endPoint}/api/{name.Substring(1, name.Length - 1).ToLower()}")
			});
		}

		protected override void ApplyEndPoint(ServiceHost host, Binding binding)
		{
			host.Description.Behaviors.Add(new ServiceMetadataBehavior
			{
				HttpGetEnabled = true
			});
			host.AddServiceEndpoint(Interface, binding, Uri[0]);
			foreach (ServiceEndpoint item in host.Description.Endpoints.ToList())
			{
				item.Behaviors.Add(new WebHttpBehavior());
			}
		}

		protected void ApplyAuthenticationManager(ServiceHostBase host, bool controller)
		{
			if (controller)
			{
				host.Authentication.ServiceAuthenticationManager = new ControllerAuthenticationManager(Container.GetInstance<IUsuarioAppService>(), Container.GetInstance<ITokenAppService>(), Container.GetInstance<IAuthAppService>(), Container.GetInstance<IHabilitacaoAppService>());
			}
			else
			{
				host.Authentication.ServiceAuthenticationManager = new ServerApiAuthenticationManager(Container.GetInstance<IUsuarioAppService>(), Container.GetInstance<ITokenAppService>(), Container.GetInstance<IHabilitacaoAppService>());
			}
		}

		protected void ApplyAuthorizationPolicy(ServiceHostBase host)
		{
			List<IAuthorizationPolicy> list = new List<IAuthorizationPolicy>
			{
				new ServerAuthorizationPolicy()
			};
			host.Authorization.ExternalAuthorizationPolicies = list.AsReadOnly();
			host.Authorization.PrincipalPermissionMode = PrincipalPermissionMode.Custom;
		}
	}
}
