			_mensagemAppService = mensagemAppService;
		}

		public async Task<ApiData<IEnumerable<OpcaoNotificacaoDto>>> Obter()
		{
			ApiData<IEnumerable<OpcaoNotificacaoDto>> result = new ApiData<IEnumerable<OpcaoNotificacaoDto>>();
			try
			{
				result.Data = await _appService.Obter();
			}
			catch (Exception ex)
			{
				result.Exception = ex.Message;
			}
			return result;
		}

		public void EnviarMensagem(string notificacaoMensagem)
		{
			NotificacaoMensagemDto notificacaoMensagemDto = new JavaScriptSerializer(new SimpleTypeResolver()).Deserialize<NotificacaoMensagemDto>(notificacaoMensagem);
