	[WebHttp(Endpoint = "restaurantemobile")]
	public class RestauranteController : IRestauranteController
	{
		private readonly IUsuarioIdentity _usuarioIdentity;

		private readonly IPedidoRestauranteAppService _appService;

		private readonly IImpressoraAppService _impressoraAppService;

		private readonly IRestauranteMobileAppService _restauranteMobileAppService;

		public RestauranteController(IUsuarioIdentity usuarioIdentity, IPedidoRestauranteAppService appService, IImpressoraAppService impressoraAppService, IRestauranteMobileAppService restauranteMobileAppService)
		{
			_usuarioIdentity = usuarioIdentity;
			_appService = appService;
			_impressoraAppService = impressoraAppService;
			_restauranteMobileAppService = restauranteMobileAppService;
		}

		public async Task<ApiData<IEnumerable<ImpressoraDto>>> ObterAmbientesProducao()
		{
			return await _impressoraAppService.ObterAmbientesProducaoApi();
		}

		public async Task<ApiData<bool>> EstenderHorario(string ambienteProducaoReferencia, string fechamento)
		{
			return await _impressoraAppService.EstenderHorario(ambienteProducaoReferencia, fechamento);
		}

		public async Task<ApiData<IEnumerable<PedidoPainelRestauranteMobileDto>>> ObterPedidos(string ambienteProducaoReferencia)
		{
			ApiData<IEnumerable<ItemPedidoRestauranteDto>> apiData = await _appService.ObterPedidosApi(_usuarioIdentity.IdEmpresa, ambienteProducaoReferencia);
			List<PedidoPainelRestauranteMobileDto> data = (from g in apiData.Data
				group g by new { g.Situacao, g.NumeroMesa, g.NumeroMesaConta, g.NumeroPedido, g.Delivery, g.PessoaNome } into itens
				select new PedidoPainelRestauranteMobileDto
				{
					Situacao = itens.Key.Situacao,
					NumeroMesa = itens.Key.NumeroMesa,
					NumeroMesaConta = itens.Key.NumeroMesaConta,
					DataHora = itens.Min((ItemPedidoRestauranteDto i) => i.DataHora.ToString("dd/MM/yyyy HH:mm")),
					Itens = itens,
					NumeroPedido = itens.Key.NumeroPedido,
					Delivery = itens.Key.Delivery,
					PessoaNome = itens.Key.PessoaNome
				}).ToList();
			return new ApiData<IEnumerable<PedidoPainelRestauranteMobileDto>>
			{
				Data = data,
				Exception = apiData.Exception
			};
		}

		public async Task<ApiData<bool>> IniciarPedido(string itens)
		{
			return await _appService.AlterarSituacao(_usuarioIdentity.IdEmpresa, _usuarioIdentity.NomeUsuario, itens, SituacaoItemPedidoRestaurante.Iniciado);
		}

		public async Task<ApiData<bool>> TerminarPedido(string itens)
		{
			return await _appService.AlterarSituacao(_usuarioIdentity.IdEmpresa, _usuarioIdentity.NomeUsuario, itens, SituacaoItemPedidoRestaurante.Pronto);
		}

		public async Task<ApiData<bool>> EntregarPedido(string itens)
		{
			return await _appService.AlterarSituacao(_usuarioIdentity.IdEmpresa, _usuarioIdentity.NomeUsuario, itens, SituacaoItemPedidoRestaurante.Entregue);
		}

