	[ServiceBehavior(InstanceContextMode = InstanceContextMode.PerCall, ConcurrencyMode = ConcurrencyMode.Multiple)]
	[ApplicationErrorHandler]
	[WebHttp(Endpoint = "atualizacao", Streamed = true)]
	public class AtualizacaoEstacaoController : IAtualizacaoEstacaoController
	{
		private static readonly SemaphoreSlim Downloads = new SemaphoreSlim(4);

		private static readonly Regex FormatoSha256 = new Regex("^[0-9a-f]{64}$", RegexOptions.Compiled);

		public RespostaApi<StatusDistribuicaoDto> Status()
		{
			RespostaApi<StatusDistribuicaoDto> respostaApi = new RespostaApi<StatusDistribuicaoDto>();
			try
			{
				bool habilitado = AtualizacaoHabilitadaNaConfiguracao() && DistribuicaoPublicada.Atual != null;
				respostaApi.Data = new StatusDistribuicaoDto
				{
					Habilitado = habilitado,
					Release = InformacoesSistema.ObterReleaseSistema()
				};
			}
			catch (Exception ex)
			{
				respostaApi.Exception = ex.Message;
			}
			return respostaApi;
		}

		public RespostaApi<ManifestoAssinadoDto> Manifesto()
		{
			RespostaApi<ManifestoAssinadoDto> respostaApi = new RespostaApi<ManifestoAssinadoDto>();
			try
			{
				DistribuicaoPublicada atual = DistribuicaoPublicada.Atual;
				if (atual == null || atual.Release != InformacoesSistema.ObterReleaseSistema())
				{
					throw new InvalidOperationException("Distribuição não publicada para esta release");
				}
				respostaApi.Data = new ManifestoAssinadoDto
				{
					Conteudo = atual.Texto,
					Assinatura = atual.Assinatura
				};
			}
			catch (Exception ex)
			{
				respostaApi.Exception = ex.Message;
			}
			return respostaApi;
		}

		public Stream Arquivo(string sha256)
		{
			OutgoingWebResponseContext outgoingWebResponseContext = WebOperationContext.Current?.OutgoingResponse;
			DistribuicaoPublicada atual = DistribuicaoPublicada.Atual;
			if (string.IsNullOrEmpty(sha256) || !FormatoSha256.IsMatch(sha256) || atual == null || !atual.Contem(sha256))
			{
				return Recusar(outgoingWebResponseContext, HttpStatusCode.NotFound);
			}
			if (!Downloads.Wait(TimeSpan.FromSeconds(2.0)))
			{
				outgoingWebResponseContext?.Headers.Add("Retry-After", "5");
				return Recusar(outgoingWebResponseContext, HttpStatusCode.ServiceUnavailable);
			}
			try
			{
				FileStream fileStream = new FileStream(DistribuicaoPublicada.CaminhoObjeto(sha256), FileMode.Open, FileAccess.Read, FileShare.Read, 81920);
				if (outgoingWebResponseContext != null)
				{
					outgoingWebResponseContext.ContentType = "application/octet-stream";
					outgoingWebResponseContext.ContentLength = fileStream.Length;
				}
				return new StreamQueLibera(fileStream, delegate
				{
					Downloads.Release();
				});
			}
			catch
			{
				Downloads.Release();
				return Recusar(outgoingWebResponseContext, HttpStatusCode.NotFound);
			}
		}

		private static Stream Recusar(OutgoingWebResponseContext resposta, HttpStatusCode status)
		{
			if (resposta != null)
			{
				resposta.StatusCode = status;
			}
			return Stream.Null;
		}

		private static bool AtualizacaoHabilitadaNaConfiguracao()
		{
			try
			{
				return new XmlConfiguracaoServerFile().Read<ConfiguracaoServer>().AtualizarEstacoesAutomaticamente;
			}
			catch
			{
				return true;
			}
		}
	}
	public class DistribuicaoPublicada
	{
		private static readonly object Trava = new object();

		private static DistribuicaoPublicada _atual;

		private static DateTime _escritaManifesto;

		private static DateTime _escritaAssinatura;

		private readonly HashSet<string> _hashes;

		public string Release { get; }

		public string Texto { get; }

		public string Assinatura { get; }

		public static string DiretorioRaiz => Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "Distribuicao");

		public static DistribuicaoPublicada Atual
		{
			get
			{
				lock (Trava)
				{
					try
					{
						string path = Path.Combine(DiretorioRaiz, "Distribuicao.xml");
						string path2 = Path.Combine(DiretorioRaiz, "Distribuicao.ass");
						if (!File.Exists(path) || !File.Exists(path2))
						{
							return _atual = null;
						}
						DateTime lastWriteTimeUtc = File.GetLastWriteTimeUtc(path);
						DateTime lastWriteTimeUtc2 = File.GetLastWriteTimeUtc(path2);
						if (_atual != null && lastWriteTimeUtc == _escritaManifesto && lastWriteTimeUtc2 == _escritaAssinatura)
						{
							return _atual;
						}
						string texto = File.ReadAllText(path);
						string assinatura = File.ReadAllText(path2).Trim();
						ManifestoDistribuicao manifestoDistribuicao = SerializadorManifesto.DeTexto(texto);
						_atual = new DistribuicaoPublicada(manifestoDistribuicao.Release, texto, assinatura, new HashSet<string>(manifestoDistribuicao.TodosOsHashes()));
						_escritaManifesto = lastWriteTimeUtc;
						_escritaAssinatura = lastWriteTimeUtc2;
						return _atual;
					}
					catch
					{
						return null;
					}
				}
			}
		}

		private DistribuicaoPublicada(string release, string texto, string assinatura, HashSet<string> hashes)
		{
			Release = release;
			Texto = texto;
			Assinatura = assinatura;
			_hashes = hashes;
		}

		public bool Contem(string sha256)
		{
			return _hashes.Contains(sha256);
		}

		public static string CaminhoObjeto(string sha256)
		{
			return Path.Combine(DiretorioRaiz, "Objetos", sha256);
		}
	}
	public class StreamQueLibera : Stream
	{
		private readonly Stream _interno;

		private Action _aoFechar;

		public override bool CanRead => _interno.CanRead;

		public override bool CanSeek => false;

		public override bool CanWrite => false;

		public override long Length => _interno.Length;

		public override long Position
		{
			get
			{
				return _interno.Position;
			}
			set
			{
				throw new NotSupportedException();
			}
		}

		public StreamQueLibera(Stream interno, Action aoFechar)
		{
			_interno = interno;
			_aoFechar = aoFechar;
		}

		public override void Flush()
		{
		}

		public override int Read(byte[] buffer, int offset, int count)
		{
			return _interno.Read(buffer, offset, count);
		}

		public override long Seek(long offset, SeekOrigin origin)
		{
			throw new NotSupportedException();
		}

		public override void SetLength(long value)
		{
			throw new NotSupportedException();
		}

		public override void Write(byte[] buffer, int offset, int count)
		{
			throw new NotSupportedException();
		}

		protected override void Dispose(bool disposing)
		{
			if (disposing)
			{
				_interno.Dispose();
				Interlocked.Exchange(ref _aoFechar, null)?.Invoke();
			}
			base.Dispose(disposing);
		}
	}
}
namespace DigisatServer.Distributed.Wcf.Main.Clients
{
	public class ChannelFactoryBasico
	{
		private readonly EndPointWcf _endPoint;

		private readonly object _sync = new object();

		public ChannelFactoryBasico(EndPointWcf endPoint)
		{
			_endPoint = endPoint;
		}

		public TContract CriarCanal<TContract>()
		{
			lock (_sync)
			{
				GerarLog gerarLog = new GerarLog();
				string name = typeof(TContract).Name;
				BasicHttpBinding basicHttpBinding = ((name.ToLower().Contains("informacao") || name.ToLower().Contains("pdvoffline")) ? new BasicHttpBinding
				{
					UseDefaultWebProxy = false,
					MaxReceivedMessageSize = 2147483647L,
					OpenTimeout = TimeSpan.FromSeconds(5.0),
					ReceiveTimeout = TimeSpan.FromSeconds(5.0),
					CloseTimeout = TimeSpan.FromSeconds(5.0),
					SendTimeout = TimeSpan.FromSeconds(5.0)
				} : new BasicHttpBinding
				{
					UseDefaultWebProxy = false,
					MaxReceivedMessageSize = 2147483647L
				});
				gerarLog.GravarLog($"Contract: {name} CloseTimeout: {basicHttpBinding.CloseTimeout} OpenTimeout: {basicHttpBinding.OpenTimeout} SendTimeout: {basicHttpBinding.SendTimeout} ReceiveTimeout: {basicHttpBinding.ReceiveTimeout}");
				return new ChannelFactory<TContract>(basicHttpBinding).CreateChannel(new EndpointAddress(new Uri($"http://{_endPoint}/{typeof(TContract).Name}")));
			}
		}
	}
	public class ChannelFactoryProtegido
	{
		private readonly EndPointWcf _endPoint;

		private readonly object _sync = new object();

		private Credentials _credenciais;

		private readonly ContentEncryptionType _contentEncryption;

		public ChannelFactoryProtegido(EndPointWcf endPoint, Credentials credenciais, ContentEncryptionType contentEncryption)
		{
			_endPoint = endPoint;
			_credenciais = credenciais;
			_contentEncryption = contentEncryption;
		}

		public TContract CriarCanal<TContract>()
		{
			lock (_sync)
			{
				ClientMessageInspector clientMessageInspector = new ClientMessageInspector();
				clientMessageInspector.BeforeSendRequested += MessageInspectorOnBeforeSendRequested;
				clientMessageInspector.AfterReceiveReplied += MessageInspectorOnAfterReceiveReplied;
				clientMessageInspector.DeveInspecionarResposta = EhRespostaComToken;
				string name = typeof(TContract).Name;
				return new ChannelFactory<TContract>((name.ToLower().Contains("arquivospedfiscal") || name.ToLower().Contains("arquivoinventario") || name.ToLower().Contains("demonstrativoresultado") || name.ToLower().Contains("imendes") || name.ToLower().Contains("arquivoefdcontribuicao") || name.ToLower().Contains("geradorarquivocontabilidade") || name.ToLower().Contains("arquivosintegra") || name.ToLower().Contains("relacionamentocliente") || name.ToLower().Contains("importacaoguiadafarmacia") || name.ToLower().Contains("importacaoabcfarma")) ? new ClientCustomBinding(_contentEncryption)
				{
					OpenTimeout = TimeSpan.FromHours(12.0),
					ReceiveTimeout = TimeSpan.FromHours(12.0),
					CloseTimeout = TimeSpan.FromHours(12.0),
					SendTimeout = TimeSpan.FromHours(12.0)
				} : new ClientCustomBinding(_contentEncryption))
				{
					Endpoint = 
					{
						Behaviors = { (IEndpointBehavior)clientMessageInspector }
					}
				}.CreateChannel(new EndpointAddress(new Uri($"http://{_endPoint}/{name}")));
			}
		}

		private void MessageInspectorOnBeforeSendRequested(object sender, MessageInspectorArgs messageInspectorArgs)
		{
			messageInspectorArgs.Message.Headers.Add(_credenciais.ToMessageHeader());
		}

		private static bool EhRespostaComToken(Message resposta)
		{
			string action = resposta.Headers.Action;
			if (!string.IsNullOrEmpty(action))
			{
				return action.EndsWith("LogOnResponse", StringComparison.OrdinalIgnoreCase);
			}
			return true;
		}

		private void MessageInspectorOnAfterReceiveReplied(object sender, MessageInspectorArgs messageInspectorArgs)
		{
			XNode xNode = XNode.ReadFrom(messageInspectorArgs.Message.GetReaderAtBodyContents());
			if (((XElement)xNode).Name.LocalName == "LogOnResponse")
			{
				_credenciais = new Credentials(_credenciais.IdEmpresa, _credenciais.NomeUsuario, _credenciais.Senha, ((XElement)xNode).Value);
			}
		}

		public void Atualizar(Credentials credenciais)
		{
			lock (_sync)
			{
				_credenciais = credenciais;
			}
		}
	}
	public sealed class ClientService : IClientService, IDisposable
	{
		private readonly EndPointWcf _endPoint;

		private static Credentials _credentials;

		private ConcurrentDictionary<string, ICommunicationObject> _channels;

		private readonly object _sync = new object();

		public ClientService(EndPointWcf endPoint)
		{
			_endPoint = endPoint;
			_channels = new ConcurrentDictionary<string, ICommunicationObject>();
			CriarCredentials();
		}

		public void SetarXmlKey(string xmlKey)
		{
		}

		private string Inicializar()
		{
			InformacaoServidorDto informacaoServidorDto = Canal((IInformacaoModuleService service) => service.ObterInformacoes());
			SetarXmlKey(informacaoServidorDto.XmlKey);
			return informacaoServidorDto.Release.ToStringEmptyWhenNull();
		}

		public ClientService SetarNomeUsuario(string nomeUsuario)
		{
			CriarCredentials(_credentials.IdEmpresa, nomeUsuario, _credentials.Senha, _credentials.IdToken);
			return this;
		}

		private void CriarCredentials(string idEmpresa = "", string nomeUsuario = "", string senha = "", string token = "")
		{
			_credentials = new Credentials(idEmpresa, nomeUsuario, senha, token);
		}

		public ClientService SetarSenha(string senha)
		{
			CriarCredentials(_credentials.IdEmpresa, _credentials.NomeUsuario, senha, _credentials.IdToken);
			return this;
		}

		public ClientService SetarIdEmpresa(string idEmpresa)
		{
			CriarCredentials(idEmpresa, _credentials.NomeUsuario, _credentials.Senha, _credentials.IdToken);
			return this;
		}

		public ClientService SetarIdToken(string token)
		{
			CriarCredentials(_credentials.IdEmpresa, _credentials.NomeUsuario, _credentials.Senha, token);
			return this;
		}

		public void Canal<TContract>(Action<TContract> action)
		{
			ICommunicationObject communicationObject = CriarCanal<TContract>();
			try
			{
				action?.Invoke((TContract)communicationObject);
			}
			catch (FaultException<ApplicationServiceError> ex)
			{
				throw new Exception(ex.Message);
			}
			catch (FaultException ex2)
			{
				throw new Exception(ex2.Message);
			}
			catch (EndpointNotFoundException)
			{
				throw new Exception("Falha ao acessar endereço do serviço. Tente novamente!");
			}
			catch (CommunicationException)
			{
				Reiniciar();
				throw new Exception("Falha de comunicação");
			}
			catch (TimeoutException)
			{
				throw new Exception("Timeout");
			}
		}

		public string Reiniciar()
		{
			lock (_sync)
			{
				FecharCanais();
				_channels.Clear();
				return Inicializar();
			}
		}

		private ICommunicationObject CriarCanal<TContract>()
		{
			_channels.TryGetValue(typeof(TContract).Name, out var channel);
			if (channel != null)
			{
				return channel;
			}
			if (typeof(TContract).GetCustomAttributes(typeof(ProtectedAttribute), inherit: true).Length != 0)
			{
				channel = new ChannelFactoryProtegido(_endPoint, _credentials, ContentEncryptionType.All).CriarCanal<TContract>() as ICommunicationObject;
			}
			else if (typeof(TContract).GetCustomAttributes(typeof(NoProtectedAttribute), inherit: true).Length != 0)
			{
				channel = new ChannelFactoryProtegido(_endPoint, _credentials, ContentEncryptionType.None).CriarCanal<TContract>() as ICommunicationObject;
			}
			else
			{
				channel = new ChannelFactoryBasico(_endPoint).CriarCanal<TContract>() as ICommunicationObject;
			}
			_channels.AddOrUpdate(typeof(TContract).Name, (string s) => channel, (string s, ICommunicationObject o) => channel);
			return channel;
		}

		public TResult Canal<TContract, TResult>(Func<TContract, TResult> func)
		{
			ICommunicationObject communicationObject = CriarCanal<TContract>();
			try
			{
				return func((TContract)communicationObject);
			}
			catch (FaultException<ApplicationServiceError> ex)
			{
				throw new Exception(ex.Message);
			}
			catch (FaultException ex2)
			{
				throw new Exception(ex2.Message);
			}
			catch (EndpointNotFoundException)
			{
				throw new Exception("Falha ao acessar endereço do serviço. Tente novamente!");
			}
			catch (CommunicationException)
			{
				Reiniciar();
				throw new Exception("Falha de comunicação");
			}
			catch (TimeoutException)
			{
				throw new Exception("Timeout");
			}
		}

		private void FecharCanais()
		{
			foreach (KeyValuePair<string, ICommunicationObject> channel in _channels)
			{
				channel.Value.Close();
			}
		}

		~ClientService()
		{
			Dispose(disposeManaged: false);
		}

		public void Dispose()
		{
			Dispose(disposeManaged: true);
			GC.SuppressFinalize(this);
		}

		private void Dispose(bool disposeManaged)
		{
			if (!disposeManaged)
			{
				return;
			}
			lock (_sync)
			{
				FecharCanais();
				_channels.Clear();
				_channels = null;
				_credentials = null;
			}
		}
	}
	public interface IClientService
	{
		void Canal<TContract>(Action<TContract> action);

		TResult Canal<TContract, TResult>(Func<TContract, TResult> func);

		string Reiniciar();
	}
}
