	[ServiceBehavior(InstanceContextMode = InstanceContextMode.PerCall, ConcurrencyMode = ConcurrencyMode.Multiple)]
	[ApplicationErrorHandler]
	public class InformacaoModuleService : IInformacaoModuleService
	{
		private readonly IConfiguracaoServidorAppService _configuracaoServidorAppService;

		private readonly IUsuarioIdentity _usuarioIdentity;

		private readonly IHabilitacaoAppService _habilitacaoAppService;

		public InformacaoModuleService(IConfiguracaoServidorAppService configuracaoServidorAppService, IUsuarioIdentity usuarioIdentity, IHabilitacaoAppService habilitacaoAppService)
		{
			_configuracaoServidorAppService = configuracaoServidorAppService;
			_usuarioIdentity = usuarioIdentity;
			_habilitacaoAppService = habilitacaoAppService;
		}

		public InformacaoServidorDto ObterInformacoes()
		{
			return new InformacaoServidorDto
			{
				XmlKey = Cryptographer.RsaServiceProvider.ToXmlString(includePrivateParameters: false),
				DateTime = DateTime.Now,
				Release = InformacoesSistema.ObterReleaseSistema().ToStringEmptyWhenNull()
			};
		}

		public DadosCertificadoDigitalDto ObterDadosCertificadoDigital()
		{
			try
			{
				ConfiguracaoServidorDto configuracaoServidorDto = _configuracaoServidorAppService.Obter(_usuarioIdentity.IdEmpresa);
				CertificadoDigital certificadoDigital = CertificadoDigital.CriarIgnorandoVigencia(configuracaoServidorDto.NFe.CertificadoDigitalNFeThumbPrint.Valor);
				int diasParaVencer = certificadoDigital.DiasParaVencer;
				int num = configuracaoServidorDto.NFe.DiasAvisoVencimentoCertificado?.Valor ?? 30;
				int num2 = configuracaoServidorDto.NFe.DiasAvisoCriticoVencimentoCertificado?.Valor ?? 5;
				return new DadosCertificadoDigitalDto
				{
					MensagemValidade = certificadoDigital.MensagemValidade,
					DataFinal = certificadoDigital.DataFinal,
					DiasParaVencer = diasParaVencer,
					Vencido = certificadoDigital.Vencido,
					ExibirAviso = (certificadoDigital.Vencido || (num > 0 && diasParaVencer <= num)),
					ExibirAvisoAoEntrar = (certificadoDigital.Vencido || (num2 > 0 && diasParaVencer <= num2))
				};
			}
			catch (Exception)
			{
				return null;
			}
		}

		public DadosArquivoHabilitacao ObterDadosArquivoHabilitacao()
		{
			return _habilitacaoAppService.ObterDadosArquivoHabilitacao();
		}

		public string ObterArquivoHabilitacao()
		{
			return _habilitacaoAppService.ObterArquivoHabilitacao();
		}
	}
