	[ServiceBehavior(InstanceContextMode = InstanceContextMode.PerCall, ConcurrencyMode = ConcurrencyMode.Multiple)]
	[ApplicationErrorHandler]
	[WebHttp]
	public class UsuariosApiService : IUsuariosApiService
	{
		private readonly ITokenAppService _tokenAppService;

		private readonly IUsuarioAppService _usuarioAppService;

		private readonly IPessoaAppService _pessoaAppService;

		private readonly IHabilitacaoAppService _habilitacaoAppService;

		public UsuariosApiService(IUsuarioAppService usuarioAppService, IHabilitacaoAppService habilitacaoAppService, ITokenAppService tokenAppService, IPessoaAppService pessoaAppService)
		{
			_usuarioAppService = usuarioAppService;
			_habilitacaoAppService = habilitacaoAppService;
			_tokenAppService = tokenAppService;
			_pessoaAppService = pessoaAppService;
		}

		public ApiData<bool> testar()
		{
			return new ApiData<bool>
			{
				Data = true
			};
		}

		public async Task<ApiData<IEnumerable<UsuarioMobileDto>>> obter(string pagina, string tamanho)
		{
			return await _usuarioAppService.Obter(pagina, tamanho);
		}

		public async Task<ApiData<IEnumerable<EmpresaMobileDto>>> emitentes(string pagina, string tamanho)
		{
			return await _pessoaAppService.Emitentes(pagina, tamanho);
		}

		public async Task<ApiData<string>> autenticar()
		{
			WebHeaderCollection headers = WebOperationContext.Current.IncomingRequest.Headers;
			string nomeUsuario = headers["nome-usuario"];
			string senha = headers["senha"];
			string idEmpresa = headers["id-empresa"];
			return await ValidarUsuario(idEmpresa, nomeUsuario, senha, string.Empty);
		}

		public async Task<ApiData<string>> revalidar()
		{
			WebHeaderCollection headers = WebOperationContext.Current.IncomingRequest.Headers;
			string nomeUsuario = headers["nome-usuario"];
			string senha = headers["senha"];
			string idEmpresa = headers["id-empresa"];
			string token = headers["token"];
			return await ValidarUsuario(idEmpresa, nomeUsuario, senha, token);
		}

		public async Task ExecutarLogOff(string nomeUsuario, string token)
		{
			await Task.Factory.StartNew(delegate
			{
				_tokenAppService.RemoverToken(nomeUsuario, token);
			});
		}

		private async Task<ApiData<string>> ValidarUsuario(string idEmpresa, string nomeUsuario, string senha, string token)
		{
			ApiData<string> result = new ApiData<string>();
			try
			{
				if (!(await _usuarioAppService.ObterPerfis(nomeUsuario)).Any((PerfilEmpresaDto perfil) => perfil.Empresa.Id.Equals(idEmpresa)))
				{
					throw new Exception("Usuário não autorizado a fazer login na empresa selecionada.");
				}
				_habilitacaoAppService.Validar(idEmpresa, _tokenAppService.ObterNumeroTokensOnline(idEmpresa, token));
				IReadOnlyDictionary<string, string[]> roles = await _usuarioAppService.ObterRoles(nomeUsuario, senha);
				string data = _tokenAppService.AdicionarToken(idEmpresa, nomeUsuario, roles, token);
				result.Data = data;
			}
			catch (Exception ex)
			{
				result.Exception = ex.Message;
			}
			return result;
		}
	}
