	[ApplicationErrorHandler]
	[Protected]
	public class AutenticacaoModuleService : IAutenticacaoModuleService
	{
		private readonly IUsuarioAppService _usuarioAppService;

		private readonly ITokenAppService _tokenAppService;

		private readonly IHabilitacaoAppService _habilitacaoAppService;

		private readonly IUsuarioIdentity _usuarioIdentity;

		public AutenticacaoModuleService(IUsuarioAppService usuarioAppService, ITokenAppService tokenAppService, IHabilitacaoAppService habilitacaoAppService, IUsuarioIdentity usuarioIdentity)
		{
			_usuarioAppService = usuarioAppService;
			_tokenAppService = tokenAppService;
			_habilitacaoAppService = habilitacaoAppService;
			_usuarioIdentity = usuarioIdentity;
		}

		[Permissao(SecurityAction.Demand, Modulo = 9999, Direito = 4)]
		public async Task<string> ExecutarLogOnAsync()
		{
			return await Task.Factory.StartNew(delegate
			{
				_habilitacaoAppService.Validar(_usuarioIdentity.IdEmpresa, _tokenAppService.ObterNumeroTokensOnline(_usuarioIdentity.IdEmpresa, _usuarioIdentity.IdToken));
				return _tokenAppService.AdicionarToken(_usuarioIdentity.IdEmpresa, _usuarioIdentity.NomeUsuario, _usuarioIdentity.Roles, _usuarioIdentity.IdToken);
			});
		}

		[Permissao(SecurityAction.Demand, Modulo = 9999, Direito = 4)]
		public async Task ExecutarLogOffAsync()
		{
			await Task.Factory.StartNew(delegate
			{
				_tokenAppService.RemoverToken(_usuarioIdentity.NomeUsuario, _usuarioIdentity.IdToken);
			});
		}

		public async Task<IEnumerable<PerfilEmpresaDto>> ObterPerfis()
		{
			return await _usuarioAppService.ObterPerfis(_usuarioIdentity.Name);
		}
	}
